import type { ActivityLogEntry, TeamInfo } from "@hunt/public-client";
import { useGlobalVolume } from "@hunt/puzzle-components";
import { type SocketState } from "@hunt/socket-manager";
import React, { useEffect, useRef, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import tileSolveSound from "../assets/solve_single_level.mp3";
import { formatActivityLogEntry } from "../components/ActivityLog";
import NavBar, { type NavBarState } from "../components/NavBar";
import Notifications, {
  type NotificationVariant,
  type NotificationsHandle,
} from "../components/Notifications";
import { PuzzleIcon } from "../components/PuzzleAndTaskDisplay/PuzzleCard";
import globalDatasetManager from "./DatasetManager";
import useDataset from "./useDataset";

const NOTIFICATION_HIGH_WATER_MARK = "notificationHighWaterMark";

const getNotificationVariant = (
  entry: ActivityLogEntry,
): NotificationVariant => {
  switch (entry.type) {
    case "erratum_issued":
      return "errata";
    case "puzzle_solved":
      return "solved";
    case "teams_notified":
      return "announcement";
    default:
      return "default";
  }
};

function getNotificationHighWaterMark(
  pageRenderEpoch: number,
  localStorageKey: string,
): number {
  // We show notifications for activity logs that are newer than BOTH the
  // latest epoch as of page load time (so you don't get a ton of notifications
  // when you log on for the first time, or come back to the page after a while),
  // AND the latest epoch that we've already shown a notification for because
  // the page-render epoch can be stale / from the cache, so you'd get
  // duplicates when navigating forward/back in history.
  const epochStr = localStorage.getItem(localStorageKey);
  if (!epochStr) {
    return pageRenderEpoch;
  }

  const parsed = parseInt(epochStr, 10);
  if (isNaN(parsed)) {
    return pageRenderEpoch;
  }

  return Math.max(parsed, pageRenderEpoch);
}

const NavBarManager = ({
  initialTeamInfo,
  initialState,
}: {
  initialTeamInfo: TeamInfo;
  initialState: NavBarState;
}) => {
  const info = useDataset("team_info", undefined, initialTeamInfo);
  const state = useDataset("navbar", undefined, initialState);
  const notifications = useRef<NotificationsHandle | null>(null);
  const highWaterMarkRef = useRef(
    getNotificationHighWaterMark(
      initialState.epoch,
      NOTIFICATION_HIGH_WATER_MARK,
    ),
  );

  const [audio, setAudio] = useState<HTMLAudioElement | null>(null);
  const [audioPlaying, setAudioPlaying] = useState(false);
  const globalVolume = useGlobalVolume();

  useEffect(() => {
    if (audio) {
      audio.volume = globalVolume;
    }

    if (audio && !audioPlaying) {
      setAudioPlaying(true);

      let didStop = false;
      const handleStop = () => {
        if (didStop) return;
        didStop = true;
        setAudioPlaying(false);
        setAudio(null);
      };

      void audio.play().catch((error: unknown) => {
        console.error("Failed to play solve sound:", error);
        handleStop();
      });

      // `ended` only fires when playback reaches the end; we also want to reset
      // state when playback stops for other reasons (pause/abort/src cleared/etc).
      audio.onended =
        audio.onpause =
        audio.onabort =
        audio.onemptied =
        audio.onstalled =
        audio.onerror =
          handleStop;
    }
  }, [globalVolume, audio, audioPlaying]);

  useEffect(() => {
    // This will clean up the audio element when the component unmounts.
    return () => {
      if (audio) {
        audio.pause();
        audio.src = "";
      }
    };
  }, [audio]);

  useEffect(() => {
    const generalStop = globalDatasetManager.watch(
      "activity_log",
      undefined,
      [],
      (value: object) => {
        const entry = value as ActivityLogEntry;
        if (
          entry.type === "interaction_unlocked" ||
          entry.type === "interaction_completed" ||
          entry.type === "interaction_started"
        ) {
          return;
        }

        // Handle tile level solved gates
        if (
          entry.type === "gate_completed" &&
          entry.slug.endsWith(":tile-level-solved") &&
          entry.title &&
          entry.show_notification
        ) {
          if (entry.id > highWaterMarkRef.current) {
            highWaterMarkRef.current = entry.id;
            localStorage.setItem(
              NOTIFICATION_HIGH_WATER_MARK,
              entry.id.toString(),
            );

            notifications.current?.addNotification({
              key: entry.id.toString(),
              icon: <PuzzleIcon lockState="unlocked" solved />,
              description: `${entry.title} was solved!`,
              variant: "solved",
            });

            setAudio(new Audio(tileSolveSound));
          }
          return;
        }

        if (entry.id > highWaterMarkRef.current) {
          highWaterMarkRef.current = entry.id;
          localStorage.setItem(
            NOTIFICATION_HIGH_WATER_MARK,
            entry.id.toString(),
          );
          const formatted = formatActivityLogEntry(entry, true);

          if (formatted?.showNotification) {
            notifications.current?.addNotification({
              key: entry.id.toString(),
              icon: formatted.icon,
              description: formatted.description,
              variant: getNotificationVariant(entry),
            });
          }

          if (entry.type === "puzzle_solved") {
            setAudio(new Audio(entry.solve_sound));
          }
        }
      },
    );

    return () => {
      generalStop();
    };
  }, []);

  const [socketState, setSocketState] = useState<SocketState>("connected");
  useEffect(() => {
    let hasCompletedInitialWait = false;
    let initialSocketState: SocketState =
      (window as unknown as { huntConnectionState?: SocketState })
        .huntConnectionState ?? "connecting";

    function handleConnectionStateEvent(evt: Event) {
      const state = (evt as CustomEvent).detail as SocketState;
      if (hasCompletedInitialWait) {
        setSocketState(state);
      } else {
        initialSocketState = state;
      }
    }
    document.addEventListener(
      "hunt:socketStateChange",
      handleConnectionStateEvent,
    );

    const initialTimeout = setTimeout(() => {
      hasCompletedInitialWait = true;
      setSocketState(initialSocketState);
    }, 1000);

    return () => {
      clearTimeout(initialTimeout);
      document.removeEventListener(
        "hunt:socketStateChange",
        handleConnectionStateEvent,
      );
    };
  }, []);

  // Expose notifications handle globally so tile round can use it
  useEffect(() => {
    (
      window as unknown as { tileLevelNotifications?: NotificationsHandle }
    ).tileLevelNotifications = notifications.current ?? undefined;
    return () => {
      delete (
        window as unknown as { tileLevelNotifications?: NotificationsHandle }
      ).tileLevelNotifications;
    };
  }, []);

  // Update the global reference when notifications ref changes
  useEffect(() => {
    if (notifications.current) {
      (
        window as unknown as { tileLevelNotifications?: NotificationsHandle }
      ).tileLevelNotifications = notifications.current;
    }
  }, [notifications.current]);

  return (
    <>
      <Notifications ref={notifications} maxNotifications={5} />
      <NavBar info={info} state={state} socketState={socketState} />
    </>
  );
};

const navbarElem = document.getElementById("navbar");
if (navbarElem) {
  const initialTeamInfo = (window as unknown as { initialTeamInfo: TeamInfo })
    .initialTeamInfo;
  const initialNavbarState = (
    window as unknown as { initialNavBarState: NavBarState }
  ).initialNavBarState;
  hydrateRoot(
    navbarElem,
    <NavBarManager
      initialTeamInfo={initialTeamInfo}
      initialState={initialNavbarState}
    />,
  );
} else {
  console.error(
    "Couldn't mount NavBar because #navbar was nowhere to be found",
  );
}
