import { newClient } from "@hunt/public-client";
import { Button, ButtonSecondary, StyledSelect } from "@hunt/styled-ui";
import { Gift } from "lucide-react";
import React, {
  type MouseEventHandler,
  useCallback,
  useEffect,
  useState,
  type Ref,
} from "react";
import StyledDialog, { DialogActions } from "../components/StyledDialog";
import apiUrl from "../utils/apiUrl";
import { IS_STATIC_SITE, staticDisabledMessage } from "../utils/staticSite";
import {
  stopUnlockDialogClick,
  unlockCancelButtonClass,
  unlockDialogClassName,
  unlockHeaderBorderClass,
  unlockHeaderInnerClass,
  unlockHeaderTextClass,
  unlockMessageClass,
  unlockMessageErrorClass,
  unlockMessageWarningClass,
  unlockPrimaryButtonClass,
} from "./unlockModalStyles";

type ModalState =
  | {
      state: "confirming";
    }
  | {
      state: "submitting";
    }
  | {
      state: "error";
      error: string;
    }
  | {
      state: "success";
      message: string;
    };

export const ExchangeClueModal = React.forwardRef(
  function ExchangeClueModalInner(
    {
      onDismiss,
    }: {
      onDismiss: () => void;
    },
    ref: Ref<HTMLDialogElement>,
  ) {
    const [modalState, setModalState] = useState<ModalState>({
      state: "confirming",
    });
    const isStaticSite = IS_STATIC_SITE;

    const stopClickPropagation: MouseEventHandler<HTMLDialogElement> =
      useCallback((e) => {
        // We want to avoid propagating click events within the dialog outside of the dialog, so that we
        // can still have other "dismiss when an unhandled click bubbles up to me" elements in the DOM.
        e.stopPropagation();
      }, []);

    const onExchange: MouseEventHandler<HTMLButtonElement> = useCallback(() => {
      if (modalState.state !== "confirming") {
        return;
      }

      setModalState({ state: "submitting" });

      (async () => {
        const apiClient = newClient(apiUrl(), undefined);

        const result = await apiClient.exchangeStrongCurrency();

        if (result.status !== 200) {
          console.error(result);
          throw new Error(`Failed to exchange clue`);
        }

        setModalState({
          state: "success",
          message: `Exchanged 1 🔎 clue for ${result.body.currency} 🧪 RP.`,
        });
      })().catch((e: unknown) => {
        console.error(e);
        setModalState({ state: "error", error: "Failed to exchange currency" });
      });
    }, [modalState]);

    const handleClose = useCallback(() => {
      onDismiss();
      setModalState({ state: "confirming" });
    }, [onDismiss]);

    if (isStaticSite) {
      return (
        <StyledDialog ref={ref} onClick={stopClickPropagation}>
          <div
            style={{
              margin: "auto",
              width: "800px",
              maxWidth: "72vw",
              textWrap: "wrap",
            }}
          >
            <h1>Exchange clue for RP</h1>
            <p>{staticDisabledMessage("Free answers")}</p>
            <DialogActions>
              <ButtonSecondary onClick={handleClose}>Close</ButtonSecondary>
            </DialogActions>
          </div>
        </StyledDialog>
      );
    }

    return (
      <StyledDialog ref={ref} onClick={stopClickPropagation}>
        <div
          style={{
            margin: "auto",
            width: "800px",
            maxWidth: "72vw",
            textWrap: "wrap",
          }}
        >
          <h1>Exchange clue for RP</h1>
          {(modalState.state === "confirming" ||
            modalState.state === "submitting") && (
            <>
              <p>Are you sure you want to exchange 1 🔎 clue for 3 🧪 RP?</p>
              <DialogActions>
                <Button
                  onClick={onExchange}
                  disabled={modalState.state === "submitting"}
                >
                  Exchange
                </Button>
                <ButtonSecondary
                  onClick={handleClose}
                  disabled={modalState.state === "submitting"}
                >
                  Cancel
                </ButtonSecondary>
              </DialogActions>
            </>
          )}
          {modalState.state === "error" && (
            <>
              <p>{modalState.error}</p>
              <DialogActions>
                <ButtonSecondary onClick={handleClose}>Cancel</ButtonSecondary>
              </DialogActions>
            </>
          )}
          {modalState.state === "success" && (
            <>
              <p>{modalState.message}</p>
              <DialogActions>
                <ButtonSecondary onClick={handleClose}>Close</ButtonSecondary>
              </DialogActions>
            </>
          )}
        </div>
      </StyledDialog>
    );
  },
);

export type FreeAnswerPuzzle = {
  slug: string;
  title: string;
};

export const FreeAnswerModal = React.forwardRef(function FreeAnswerModalInner(
  {
    onDismiss,
    buyablePuzzles,
  }: {
    onDismiss: () => void;
    buyablePuzzles: FreeAnswerPuzzle[];
  },
  ref: Ref<HTMLDialogElement>,
) {
  const [modalState, setModalState] = useState<ModalState>({
    state: "confirming",
  });
  const isStaticSite = IS_STATIC_SITE;

  const [puzzle, setPuzzle] = useState<{ slug: string; title: string } | null>(
    null,
  );
  const hasBuyablePuzzles = buyablePuzzles?.length > 0;

  const onBuy: MouseEventHandler<HTMLButtonElement> = useCallback(() => {
    if (modalState.state !== "confirming") {
      return;
    }

    if (!puzzle) {
      return;
    }

    setModalState({ state: "submitting" });

    (async () => {
      const apiClient = newClient(apiUrl(), undefined);

      const result = await apiClient.buyPuzzleAnswer({
        params: {
          slug: puzzle.slug,
        },
      });

      if (result.status !== 200) {
        console.error(result);
        throw new Error(`Failed to buy answer`);
      }

      setModalState({
        state: "success",
        message: `Bought answer for ${puzzle.title}: ${result.body.answer}`,
      });
    })().catch((e: unknown) => {
      console.error(e);
      setModalState({
        state: "error",
        error: "Failed to exchange free answer",
      });
    });
  }, [modalState, puzzle]);

  const handleClose = useCallback(() => {
    onDismiss();
    setModalState({ state: "confirming" });
    setPuzzle(null);
  }, [onDismiss]);

  const handlePuzzleChange = useCallback(
    (event: React.ChangeEvent<HTMLSelectElement>) => {
      const slug = event.target.value;
      const selectedPuzzle = buyablePuzzles.find(
        (entry) => entry.slug === slug,
      );
      setPuzzle(selectedPuzzle ?? null);
    },
    [buyablePuzzles],
  );

  const canBuy =
    modalState.state !== "submitting" && hasBuyablePuzzles && !!puzzle;

  useEffect(() => {
    if (!puzzle) {
      return;
    }
    if (!buyablePuzzles.some((entry) => entry.slug === puzzle.slug)) {
      setPuzzle(null);
    }
  }, [buyablePuzzles, puzzle]);

  const handleDialogClick: MouseEventHandler<HTMLDialogElement> = useCallback(
    (event) => {
      if (event.target === event.currentTarget) {
        event.stopPropagation();
        handleClose();
      }
    },
    [handleClose],
  );

  const isConfirming =
    modalState.state === "confirming" || modalState.state === "submitting";

  if (isStaticSite) {
    return (
      // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
      <dialog
        ref={ref}
        className={unlockDialogClassName}
        aria-modal="true"
        onClick={handleDialogClick}
      >
        {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
        <div
          className="flex max-w-full flex-col gap-5"
          onClick={stopUnlockDialogClick}
        >
          <div className={unlockHeaderBorderClass}>
            <div className={unlockHeaderInnerClass}>
              <Gift className="h-6 w-6 text-[#153A62]" />
              <span className={unlockHeaderTextClass}>Free answers</span>
            </div>
          </div>
          <div className="flex flex-col gap-3 whitespace-normal px-4">
            <p className={unlockMessageWarningClass}>
              {staticDisabledMessage("Free answers")}
            </p>
          </div>
          <div className="flex flex-wrap justify-end gap-3 sm:flex-nowrap">
            <button
              className={unlockCancelButtonClass}
              onClick={handleClose}
              type="button"
            >
              Close
            </button>
          </div>
        </div>
      </dialog>
    );
  }

  return (
    // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
    <dialog
      ref={ref}
      className={unlockDialogClassName}
      aria-modal="true"
      onClick={handleDialogClick}
    >
      {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
      <div
        className="flex max-w-full flex-col gap-5"
        onClick={stopUnlockDialogClick}
      >
        <div className={unlockHeaderBorderClass}>
          <div className={unlockHeaderInnerClass}>
            <Gift className="h-6 w-6 text-[#153A62]" />
            <span className={unlockHeaderTextClass}>Spend 1 Free Answer?</span>
          </div>
        </div>
        <div className="flex flex-col gap-3 whitespace-normal px-4">
          <h1 className="font-headline text-white">Buy a puzzle answer?</h1>
          {isConfirming && (
            <>
              <p className={unlockMessageClass}>
                Exchange 1 free answer for the answer to a puzzle. You may only
                buy answers for non-metapuzzles in the Kingdom.
              </p>
              {hasBuyablePuzzles ? (
                <div>
                  <StyledSelect
                    value={puzzle?.slug ?? ""}
                    onChange={handlePuzzleChange}
                  >
                    <option value="">Select...</option>
                    {buyablePuzzles.map((entry) => (
                      <option key={entry.slug} value={entry.slug}>
                        {entry.title}
                      </option>
                    ))}
                  </StyledSelect>
                </div>
              ) : (
                <p className={unlockMessageWarningClass}>
                  No unlocked puzzles are available for a free answer yet.
                </p>
              )}
            </>
          )}
          {modalState.state === "error" && (
            <p className={unlockMessageErrorClass}>{modalState.error}</p>
          )}
          {modalState.state === "success" && (
            <p className={unlockMessageClass}>{modalState.message}</p>
          )}
        </div>
        <div className="flex flex-wrap justify-end gap-3 sm:flex-nowrap">
          {isConfirming ? (
            <>
              <button
                className={unlockCancelButtonClass}
                onClick={handleClose}
                disabled={modalState.state === "submitting"}
                type="button"
              >
                Cancel
              </button>
              <button
                className={unlockPrimaryButtonClass}
                onClick={onBuy}
                disabled={!canBuy}
                type="button"
              >
                Buy Answer
              </button>
            </>
          ) : (
            <button
              className={unlockCancelButtonClass}
              onClick={handleClose}
              type="button"
            >
              Close
            </button>
          )}
        </div>
      </div>
    </dialog>
  );
});
