import { CircleX } from "lucide-react";
import React, {
  type CSSProperties,
  type ReactNode,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";
import { TransitionGroup, CSSTransition } from "react-transition-group";

export type NotificationVariant =
  | "default"
  | "errata"
  | "solved"
  | "announcement";

export type Notification = {
  key: string;
  icon: ReactNode;
  description: ReactNode;
  variant?: NotificationVariant;
};

type NotificationsProps = {
  maxNotifications: number;
  persistentNotifications?: Notification[];
};

export type NotificationsHandle = {
  addNotification: (notification: Notification) => void;
};

const NOTIFICATION_TIMEOUT = 15000;

const baseNotificationClasses =
  "relative mb-4 flex min-h-[95px] w-[420px] max-w-[calc(100vw-2rem)] items-center gap-6 rounded-tl-[100px] rounded-bl-[100px] rounded-tr-3xl rounded-br-3xl pl-8 pr-2 py-2 text-base font-[var(--body-font)] shadow-[0_4px_4px_rgba(0,0,0,0.25)]";

const baseIconClasses =
  "flex h-12 w-12 shrink-0 items-center justify-center text-[28px] transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.25)]";

const dismissButtonClasses =
  "absolute right-3 top-3 flex h-5 w-5 items-center justify-center rounded-full text-[#153A6280] transition-colors hover:text-secondary";

const notificationVariantStyles: Record<
  NotificationVariant,
  { container: string; x: string; linkColor: string }
> = {
  default: {
    container:
      "bg-[linear-gradient(90deg,_#153A62_0%,_#2C599C_100%)] text-white",
    x: "text-[#95ABCD] hover:text-white",
    linkColor: "var(--accent-yellow)",
  },
  errata: {
    container:
      "bg-[linear-gradient(90deg,_#F3E372_0%,_#FFA6BB_100%)] text-secondary",
    x: "text-[#89708D] hover:text-secondary",
    linkColor: "var(--accent-blue)",
  },
  solved: {
    container:
      "bg-[linear-gradient(90deg,_#F3E372_0%,_#A6FFBB_100%)] text-secondary",
    x: "text-[#5E9C8D] hover:text-secondary",
    linkColor: "var(--accent-blue)",
  },
  announcement: {
    container:
      "bg-[linear-gradient(90deg,_#DFAEFF_13.94%,_#6CB5FF_100%)] text-secondary",
    x: "text-[#4278B0] hover:text-secondary",
    linkColor: "var(--accent-blue)",
  },
};

const NotificationCard = ({
  notification,
  onDismiss,
}: {
  notification: Notification;
  onDismiss?: () => void;
}) => {
  const variant = notification.variant ?? "default";
  const variantStyles = notificationVariantStyles[variant];
  const linkStyle: CSSProperties = {
    ["--notification-link-color" as string]: variantStyles.linkColor,
  };

  return (
    <div
      style={linkStyle}
      className={`${baseNotificationClasses} ${variantStyles.container} ${onDismiss ? "pr-10" : ""} [&_a]:!text-[var(--notification-link-color)] [&_a:visited]:!text-[var(--notification-link-color)] [&_a:hover]:!text-[var(--notification-link-color)] [&_a]:no-underline [&_a:hover]:underline`}
    >
      <div className={baseIconClasses}>{notification.icon}</div>
      <div className="flex-1 leading-snug mr-7">{notification.description}</div>
      {onDismiss ? (
        <button
          className={dismissButtonClasses}
          aria-label="Dismiss notification"
          onClick={(evt) => {
            evt.preventDefault();
            onDismiss();
          }}
        >
          <CircleX className={`h-5 w-5 ${variantStyles.x}`} strokeWidth={2.5} />
        </button>
      ) : null}
    </div>
  );
};

const Notifications = forwardRef<NotificationsHandle, NotificationsProps>(
  ({ maxNotifications, persistentNotifications = [] }, ref) => {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const timeoutIds = useRef<Map<string, number>>(new Map());

    const clearNotificationTimeout = (key: string) => {
      const timeoutId = timeoutIds.current.get(key);
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutIds.current.delete(key);
      }
    };

    const removeNotification = (key: string) => {
      clearNotificationTimeout(key);
      setNotifications((oldNotifications) =>
        oldNotifications.filter((notification) => notification.key !== key),
      );
    };

    useImperativeHandle(ref, () => ({
      addNotification: (notification: Notification) => {
        setNotifications((oldNotifications) => {
          let nextNotifications = oldNotifications;

          if (oldNotifications.length >= maxNotifications) {
            const [oldest, ...rest] = oldNotifications;
            clearNotificationTimeout(oldest.key);
            nextNotifications = rest;
          }

          nextNotifications = nextNotifications.filter(
            (n) => n.key !== notification.key,
          );

          return [...nextNotifications, notification];
        });

        clearNotificationTimeout(notification.key);

        if (typeof window !== "undefined") {
          const timeoutId = window.setTimeout(() => {
            setNotifications((currentNotifications) =>
              currentNotifications.filter(
                (existing) => existing.key !== notification.key,
              ),
            );
            timeoutIds.current.delete(notification.key);
          }, NOTIFICATION_TIMEOUT);

          timeoutIds.current.set(notification.key, timeoutId);
        }
      },
    }));

    useEffect(() => {
      const timeouts = timeoutIds.current;
      return () => {
        timeouts.forEach((timeoutId) => {
          clearTimeout(timeoutId);
        });
        timeouts.clear();
      };
    }, [timeoutIds]);

    // Define transition classes using Tailwind utilities.
    const transitionClassNames = {
      enter: "opacity-0",
      enterActive: "opacity-100 transition-opacity duration-500",
      exit: "opacity-100",
      exitActive: "opacity-0 transition-opacity duration-500",
    };

    return (
      // Notifications should be above Monarch and other modals.
      <div className="fixed top-12 right-0 p-4 z-[102] print:hidden">
        <TransitionGroup>
          {persistentNotifications.map((notification) => (
            <CSSTransition
              key={notification.key}
              timeout={500}
              classNames={transitionClassNames}
            >
              <NotificationCard notification={notification} />
            </CSSTransition>
          ))}
          {notifications.map((notification) => (
            <CSSTransition
              key={notification.key}
              timeout={500}
              classNames={transitionClassNames}
            >
              <NotificationCard
                notification={notification}
                onDismiss={() => {
                  removeNotification(notification.key);
                }}
              />
            </CSSTransition>
          ))}
        </TransitionGroup>
      </div>
    );
  },
);

Notifications.displayName = "Notifications";

export default Notifications;
