type DropdownAnchorProps = {
  onKeyDown: (ev: React.KeyboardEvent) => void;
  "aria-haspopup": "menu";
  "aria-expanded": boolean;
  "aria-controls": string;
};

type DropdownProps = {
  align?: "left" | "right" | "side";
  anchor: (props: DropdownAnchorProps) => React.ReactNode;
  menu: React.ReactNode;
  direction?: "down" | "right";
  className?: string;
  /** If true (default), this dropdown participates in top-level dropdown coordination */
  isTopLevel?: boolean;
  /** Optional prefix for generating stable IDs. If not provided, uses a counter. */
  idPrefix?: string;
};

const Dropdown: React.FC<DropdownProps> = ({
  align = "side",
  anchor,
  menu,
  direction = "right",
  className,
  isTopLevel = true,
  idPrefix,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLLIElement>(null);
  // Construct stable IDs directly - idPrefix is stable so this is safe
  const dropdownId = `${idPrefix ?? "navbar"}-dropdown`;
  const menuId = `${idPrefix ?? "navbar"}-menu`;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    };
    if (isOpen && typeof document !== "undefined") {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleEscapeKey);
    }
    return () => {
      if (typeof document !== "undefined") {
        document.removeEventListener("mousedown", handleClickOutside);
        document.removeEventListener("keydown", handleEscapeKey);
      }
    };
  }, [isOpen]);

  useEffect(() => {
    const eventName = isTopLevel ? DROPDOWN_OPEN_EVENT : SUBMENU_OPEN_EVENT;

    const handleOtherDropdownOpen = (event: Event) => {
      const customEvent = event as CustomEvent<string>;
      if (customEvent.detail !== dropdownId) {
        setIsOpen(false);
      }
    };
    if (typeof window !== "undefined") {
      window.addEventListener(eventName, handleOtherDropdownOpen);
      return () => {
        window.removeEventListener(eventName, handleOtherDropdownOpen);
      };
    }
  }, [isTopLevel, dropdownId]);

  const handleAnchorKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      setIsOpen((prev) => {
        if (!prev) {
          const eventName = isTopLevel
            ? DROPDOWN_OPEN_EVENT
            : SUBMENU_OPEN_EVENT;
          if (typeof window !== "undefined") {
            window.dispatchEvent(
              new CustomEvent(eventName, { detail: dropdownId }),
            );
          }
        } else {
          // Closing: dispatch events to close all nested submenus
          if (typeof window !== "undefined") {
            window.dispatchEvent(
              new CustomEvent(SUBMENU_OPEN_EVENT, { detail: "close-all" }),
            );
            window.dispatchEvent(
              new CustomEvent(NESTED_SUBMENU_OPEN_EVENT, {
                detail: "close-all",
              }),
            );
          }
        }
        return !prev;
      });
    }
  };

  const anchorProps: DropdownAnchorProps = {
    onKeyDown: handleAnchorKeyDown,
    "aria-haspopup": "menu",
    "aria-expanded": isOpen,
    "aria-controls": menuId,
  };

  return (
    <li
      ref={containerRef}
      className={cn("relative group/menu h-full flex list-none", className)}
    >
      {anchor(anchorProps)}
      <ul
        id={menuId}
        role="menu"
        className={cn(
          DROPDOWN_STYLING,
          "group-hover/menu:block group-hover/menu:opacity-100",
          isOpen && "flex opacity-100 pointer-events-auto",
          align === "right"
            ? "right-0"
            : align === "left"
              ? "left-full navbar-1:left-0"
              : "left-full",
          direction === "down" && "top-full",
        )}
      >
        {menu}
      </ul>
    </li>
  );
};

type TopLevelDropdownProps = {
  anchor: (props: DropdownAnchorProps) => React.ReactNode;
  menuItems: React.ReactNode;
  started: boolean;
  inlineMenuItems: React.ReactNode;
};

const TopLevelDropdown: React.FC<TopLevelDropdownProps> = ({
  anchor,
  menuItems,
  inlineMenuItems,
  started,
}) => {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  // Use stable hardcoded IDs to avoid hydration issues
  const dropdownId = "navbar-top-dropdown";
  const menuId = "navbar-top-menu";
  const menuIsOpen = mobileOpen || isHovered;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setMobileOpen(false);
      }
    };

    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setMobileOpen(false);
      }
    };

    if (mobileOpen && typeof document !== "undefined") {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleEscapeKey);
    }
    return () => {
      if (typeof document !== "undefined") {
        document.removeEventListener("mousedown", handleClickOutside);
        document.removeEventListener("keydown", handleEscapeKey);
      }
    };
  }, [mobileOpen]);

  useEffect(() => {
    const handleOtherDropdownOpen = (event: Event) => {
      const customEvent = event as CustomEvent<string>;
      if (customEvent.detail !== dropdownId) {
        setMobileOpen(false);
      }
    };
    if (typeof window !== "undefined") {
      window.addEventListener(DROPDOWN_OPEN_EVENT, handleOtherDropdownOpen);
      return () => {
        window.removeEventListener(
          DROPDOWN_OPEN_EVENT,
          handleOtherDropdownOpen,
        );
      };
    }
  }, [dropdownId]);

  const handleAnchorKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      setMobileOpen((prev) => {
        if (!prev) {
          if (typeof window !== "undefined") {
            window.dispatchEvent(
              new CustomEvent(DROPDOWN_OPEN_EVENT, {
                detail: dropdownId,
              }),
            );
          }
        } else {
          // Closing: dispatch events to close all nested submenus
          if (typeof window !== "undefined") {
            window.dispatchEvent(
              new CustomEvent(SUBMENU_OPEN_EVENT, { detail: "close-all" }),
            );
            window.dispatchEvent(
              new CustomEvent(NESTED_SUBMENU_OPEN_EVENT, {
                detail: "close-all",
              }),
            );
          }
        }
        return !prev;
      });
    }
  };

  const anchorProps: DropdownAnchorProps = {
    onKeyDown: handleAnchorKeyDown,
    "aria-haspopup": "menu",
    "aria-expanded": menuIsOpen,
    "aria-controls": menuId,
  };

  return (
    <div className="flex justify-between w-full h-full navbar-6:w-fit">
      {/* Desktop: Render the menu inline */}
      <div className="hidden navbar-1:flex navbar-1:items-center h-full">
        {inlineMenuItems}
      </div>

      {/* Mobile: Use click toggle and hover */}
      <div
        ref={containerRef}
        className={cn(
          "flex navbar-6:hidden relative w-fit",
          !started ? "navbar-1:hidden" : "",
        )}
        onMouseEnter={() => {
          setIsHovered(true);
        }}
        onMouseLeave={() => {
          setIsHovered(false);
        }}
      >
        {anchor(anchorProps)}
        <ul
          id={menuId}
          role="menu"
          className={cn(
            `absolute top-[3rem] left-0 text-navbar-text-secondary bg-navbar-secondary rounded-md flex-col z-50 transition-all duration-200 transition-discrete starting-open-opacity-0 ${
              menuIsOpen ? "" : "hidden opacity-0"
            } p-2 gap-y-2`,
          )}
        >
          {menuItems}
        </ul>
      </div>
    </div>
  );
};

type SubDropdownProps = {
  anchor: (props: DropdownAnchorProps) => React.ReactNode;
  menu: React.ReactNode;
  direction?: "down" | "right";
  align?: "left" | "right" | "side";
  className?: string;
  /** If true, this dropdown participates in top-level dropdown coordination */
  isTopLevel?: boolean;
  /** If true, this is a deeply nested submenu (inside another dropdown) */
  isNested?: boolean;
  /** Prefix for generating stable IDs. Required for uniqueness. */
  idPrefix: string;
};

const getSubDropdownEventName = (isTopLevel: boolean, isNested: boolean) => {
  if (isNested) return NESTED_SUBMENU_OPEN_EVENT;
  if (isTopLevel) return DROPDOWN_OPEN_EVENT;
  return SUBMENU_OPEN_EVENT;
};

const SubDropdown: React.FC<SubDropdownProps> = ({
  anchor,
  menu,
  direction = "right",
  align = "side",
  className,
  isTopLevel = false,
  isNested = false,
  idPrefix,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLLIElement>(null);
  // Construct stable IDs directly - idPrefix is stable so this is safe
  const dropdownId = `${idPrefix}-dropdown`;
  const menuId = `${idPrefix}-menu`;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    };

    if (isOpen && typeof document !== "undefined") {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleEscapeKey);
    }
    return () => {
      if (typeof document !== "undefined") {
        document.removeEventListener("mousedown", handleClickOutside);
        document.removeEventListener("keydown", handleEscapeKey);
      }
    };
  }, [isOpen]);

  useEffect(() => {
    const eventName = getSubDropdownEventName(isTopLevel, isNested);

    const handleOtherDropdownOpen = (event: Event) => {
      const customEvent = event as CustomEvent<string>;
      if (customEvent.detail !== dropdownId) {
        setIsOpen(false);
      }
    };
    if (typeof window !== "undefined") {
      window.addEventListener(eventName, handleOtherDropdownOpen);
      return () => {
        window.removeEventListener(eventName, handleOtherDropdownOpen);
      };
    }
  }, [isTopLevel, isNested, dropdownId]);

  const handleAnchorKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      event.stopPropagation();
      setIsOpen((prev) => {
        if (!prev) {
          const eventName = getSubDropdownEventName(isTopLevel, isNested);
          if (typeof window !== "undefined") {
            window.dispatchEvent(
              new CustomEvent(eventName, { detail: dropdownId }),
            );
          }
        }
        return !prev;
      });
    }
  };

  const anchorProps: DropdownAnchorProps = {
    onKeyDown: handleAnchorKeyDown,
    "aria-haspopup": "menu",
    "aria-expanded": isOpen,
    "aria-controls": menuId,
  };

  return (
    <li
      ref={containerRef}
      className={cn(
        "relative group/submenu flex items-center justify-center",
        className,
      )}
    >
      {anchor(anchorProps)}
      <ul
        className={cn(
          DROPDOWN_STYLING,
          "group-hover/submenu:block group-hover/submenu:opacity-100 top-0 left-full",
          isOpen && "flex opacity-100 pointer-events-auto",
          direction === "down" && "navbar-1:top-full",
          align === "right"
            ? "navbar-1:right-0 navbar-1:left-auto"
            : align === "left"
              ? "left-full navbar-1:left-0"
              : "left-full",
        )}
      >
        {menu}
      </ul>
    </li>
  );
};

