export type NavBarRoundData = {
  title: string;
  href: string;
  locked: boolean;
  // Only applicable if locked is true
  round_unlock?: {
    cost: number;
    slug: string;
    title: string;
    desc?: string;
  };
  world: string;
};

export type NavBarState = {
  epoch: number;
  rounds: NavBarRoundData[];
  currency: number;
  strongCurrency: number;
  buyablePuzzles: { slug: string; title: string }[];
  overworldPuzzlesOpen: number;
  maxOverworldWidth: number;
};

type NavBarProps = {
  info: { teamName: string };
  state: NavBarState;
  socketState: SocketState;
};

const NavBar: React.FC<NavBarProps> = ({ info, state }) => {
  const [selectedNavPath, setSelectedNavPath] = useState<string>();
  const freeAnswerModalRef = useRef<HTMLDialogElement>(null);
  const { teamName } = info;
  const {
    rounds,
    currency,
    strongCurrency,
    buyablePuzzles,
    overworldPuzzlesOpen,
    maxOverworldWidth,
  } = state;
  const isStaticSite = IS_STATIC_SITE;
  const overworldRounds = rounds.filter((round) => round.world === "overworld");
  const dimensionRounds = rounds.filter((round) => round.world === "dimension");
  const started = IS_STATIC_SITE ? true : rounds.length > 0;

  useEffect(() => {
    // Only run in client environments where `window` exists.
    if (typeof window !== "undefined") {
      setSelectedNavPath(window.location.pathname);
    }
  }, []);
  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }
    if (IS_STATIC_SITE) {
      return;
    }

    const handleOpenFreeAnswers = () => {
      freeAnswerModalRef.current?.showModal();
    };
    if (typeof window !== "undefined") {
      window.addEventListener(FREE_ANSWERS_OPEN_EVENT, handleOpenFreeAnswers);
      return () => {
        window.removeEventListener(
          FREE_ANSWERS_OPEN_EVENT,
          handleOpenFreeAnswers,
        );
      };
    }
  }, []);
  const handleFreeAnswerMenuClick: MouseEventHandler<HTMLAnchorElement> =
    useCallback((event) => {
      event.preventDefault();
      if (IS_STATIC_SITE) {
        return;
      }
      freeAnswerModalRef.current?.showModal();
    }, []);
  const handleResetLocalStateMenuClick: MouseEventHandler<HTMLAnchorElement> =
    useCallback(
      (event) => {
        event.preventDefault();
        if (typeof window === "undefined" || !isStaticSite) {
          return;
        }
        const confirmed = window.confirm(
          "Reset local state? This clears local progress and reloads the page.",
        );
        if (!confirmed) {
          return;
        }
        const runReset = async () => {
          try {
            const localState = (
              window as unknown as {
                huntLocalState?: {
                  reset: (options?: { reload?: boolean }) => Promise<void>;
                };
              }
            ).huntLocalState;

            if (localState?.reset) {
              await localState.reset({ reload: false });
            }

            if (typeof indexedDB !== "undefined") {
              const deleteDatabase = (name: string) =>
                new Promise<void>((resolve) => {
                  const request = indexedDB.deleteDatabase(name);
                  request.onsuccess = () => {
                    resolve();
                  };
                  request.onerror = () => {
                    resolve();
                  };
                  request.onblocked = () => {
                    resolve();
                  };
                });

              const names = new Set(INDEXED_DB_NAMES);
              if (typeof indexedDB.databases === "function") {
                const databases = await indexedDB.databases();
                databases.forEach((database) => {
                  if (database.name?.startsWith(TILE_ROUND_DB_PREFIX)) {
                    names.add(database.name);
                  }
                });
              }
              await Promise.allSettled(
                Array.from(names).map((name) => deleteDatabase(name)),
              );
            }

            try {
              window.localStorage?.clear();
            } catch {
              // Ignore localStorage failures.
            }
          } catch (error) {
            console.error("Failed to reset local state:", error);
          } finally {
            window.location.reload();
          }
        };

        void runReset();
      },
      [isStaticSite],
    );

  return (
    <Nav
      childrenBottom={
        <>
          {started && (
            <>
              <ConditionalTooltip
                tooltip={
                  <>
                    <div>Research points</div>
                    <div className="text-sm italic">Click to learn more</div>
                  </>
                }
                side="bottom"
                className="bg-neutral-300 text-black border-2 rounded-md border-secondary text-center"
              >
                <a
                  href={`/about#research-points-rp-and-research-tasks`}
                  className="no-underline"
                >
                  <Currency aria-label="Research points">
                    <FlaskConical width={18} className="text-rp" /> {currency}
                  </Currency>
                </a>
              </ConditionalTooltip>
              {!IS_STATIC_SITE && maxOverworldWidth && (
                <ConditionalTooltip
                  tooltip={
                    <>
                      <div>Number of Puzzmon actively being befriended</div>
                      <div>(Metas and capstones are not included)</div>
                    </>
                  }
                  side="bottom"
                  className="bg-neutral-300 text-black border-2 rounded-md border-secondary text-center"
                >
                  <Currency aria-label="Number of Puzzmon actively being befriended">
                    <Puzzle width={18} className="text-accent" />{" "}
                    {overworldPuzzlesOpen}/{maxOverworldWidth}
                  </Currency>
                </ConditionalTooltip>
              )}
            </>
          )}

          <VolumeControl />

          <Dropdown
            idPrefix="navbar-team"
            align="right"
            direction="down"
            anchor={(extraProps) => (
              <TeamNameNavLink
                tabIndex={0}
                isSelected={
                  selectedNavPath === NAVIGATION_MAPPING.MANAGE_TEAM.path ||
                  selectedNavPath === NAVIGATION_MAPPING.CONTACT.path
                }
                {...extraProps}
              >
                <span className="overflow-hidden text-ellipsis">
                  {teamName}
                </span>
              </TeamNameNavLink>
            )}
            menu={
              <ul className={MENU_STYLING}>
                {!isStaticSite && (
                  <li>
                    <NavLink
                      href={NAVIGATION_MAPPING.MANAGE_TEAM.path}
                      isMenuItem
                    >
                      {NAVIGATION_MAPPING.MANAGE_TEAM.name}
                    </NavLink>
                  </li>
                )}
                {!isStaticSite && strongCurrency > 0 && (
                  <li>
                    <NavLink
                      href="#"
                      isMenuItem
                      onClick={handleFreeAnswerMenuClick}
                    >
                      Free answers ({strongCurrency})
                    </NavLink>
                  </li>
                )}
                <li>
                  <NavLink href={NAVIGATION_MAPPING.CONTACT.path} isMenuItem>
                    {NAVIGATION_MAPPING.CONTACT.name}
                  </NavLink>
                </li>
                {isStaticSite && (
                  <li>
                    <NavLink
                      href="#"
                      isMenuItem
                      onClick={handleResetLocalStateMenuClick}
                    >
                      Reset local state
                    </NavLink>
                  </li>
                )}
                {!isStaticSite && (
                  <li>
                    <NavLink href={NAVIGATION_MAPPING.LOGOUT.path} isMenuItem>
                      {NAVIGATION_MAPPING.LOGOUT.name}
                    </NavLink>
                  </li>
                )}
              </ul>
            }
          />
        </>
      }
    >
      <NavItems>
        {/* Logo link – visible on larger screens */}
        <li className="hidden navbar-1:flex items-center justify-center -ml-5 mt-2 navbar-expanded:mt-4">
          <div className="h-[108px] w-[108px] navbar-expanded:h-[88px] navbar-expanded:w-[88px] rounded-full bg-primary flex items-center justify-center">
            <NavLink
              href={NAVIGATION_MAPPING.HOME.path}
              id="home-md"
              className="p-0 w-fit"
            >
              <img
                src={crownIcon}
                alt="Home"
                title="Home"
                className="h-24 w-24 min-w-24 navbar-expanded:h-20 navbar-expanded:w-20 navbar-expanded:min-w-20 hover:brightness-110 hover:drop-shadow-[0_0_8px_rgb(46,167,253)] focus-visible:brightness-110 focus-visible:drop-shadow-[0_0_8px_rgb(46,167,253)]"
              />
            </NavLink>
          </div>
        </li>

        {/* Top-level dropdown for the menu */}
        <TopLevelDropdown
          anchor={(extraProps) => (
            <NavLink id="menu-md" tabIndex={0} {...extraProps}>
              <Menu className="text-navbar-text-primary" />
            </NavLink>
          )}
          started={started}
          menuItems={
            <AllMenuItems
              selectedNavPath={selectedNavPath}
              started={started}
              currency={currency}
              overworldRounds={overworldRounds}
              dimensionRounds={dimensionRounds}
              isInTopLevelMenu
            />
          }
          inlineMenuItems={
            <AllMenuItems
              selectedNavPath={selectedNavPath}
              started={started}
              currency={currency}
              overworldRounds={overworldRounds}
              dimensionRounds={dimensionRounds}
            />
          }
        />
      </NavItems>

      {!isStaticSite && (
        <FreeAnswerModal
          ref={freeAnswerModalRef}
          onDismiss={() => {
            freeAnswerModalRef.current?.close();
          }}
          buyablePuzzles={buyablePuzzles}
        />
      )}
    </Nav>
  );
};

type UnlockableRoundProps = {
  round: NavBarRoundData;
  currency: number;
};

const UnlockableRound: React.FC<UnlockableRoundProps> = ({
  round,
  currency,
}) => {
  const isStaticSite = IS_STATIC_SITE;
  const [isHovered, setIsHovered] = useState(false);
  const unlockModalRef = useRef<HTMLDialogElement>(null);
  const showUnlockModal: MouseEventHandler<HTMLButtonElement> = useCallback(
    (e) => {
      e.stopPropagation();
      unlockModalRef.current?.showModal();
    },
    [],
  );
  const dismissUnlockModal = useCallback(() => {
    unlockModalRef.current?.close();
  }, []);

  if (isStaticSite) {
    return (
      <li>
        <div
          className={cn(
            MENU_ITEM_STYLING,
            "gap-1 cursor-not-allowed text-black/60",
          )}
        >
          <div className="flex items-center justify-center w-5 h-5">
            <Lock width="18" height="18" />
          </div>
          {round.title}
        </div>
      </li>
    );
  }

  return (
    <li>
      <NavButton
        onClick={showUnlockModal}
        className={cn(MENU_ITEM_STYLING, "gap-1")}
        onMouseEnter={() => {
          setIsHovered(true);
        }}
        onMouseLeave={() => {
          setIsHovered(false);
        }}
      >
        {isHovered ? (
          <LockOpen width="20" height="20" strokeWidth={2.5} />
        ) : (
          <div className="flex items-center justify-center w-5 h-5">
            <Lock width="18" height="18" />
          </div>
        )}
        {round.title}
      </NavButton>
      <RoundUnlockModal
        ref={unlockModalRef}
        onDismiss={dismissUnlockModal}
        cost={round.round_unlock?.cost ?? 1}
        currency={currency}
        slug={round.round_unlock?.slug ?? ""}
        title={round.round_unlock?.title ?? ""}
        desc={round.round_unlock?.desc}
      />
    </li>
  );
};

export default NavBar;
