import {
  VOLUME_CHANGE_EVENT,
  VOLUME_STORAGE_KEY,
  DEFAULT_VOLUME,
  type VolumeChangeEvent,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { Volume1, Volume2, VolumeX } from "lucide-react";
import React, { useEffect, useState } from "react";

type VolumeControlProps = {
  className?: string;
};

const VolumeControl: React.FC<VolumeControlProps> = ({ className }) => {
  const [volume, setVolume] = useState<number>(DEFAULT_VOLUME);
  useEffect(() => {
    if (typeof window !== "undefined") {
      const storedVolume = Number(
        window.localStorage.getItem(VOLUME_STORAGE_KEY) ?? DEFAULT_VOLUME,
      );
      setVolume(storedVolume);
    }
  }, []);
  const [isHovered, setIsHovered] = useState(false);

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseFloat(e.target.value);
    setVolume(newVol);
    window.localStorage.setItem(VOLUME_STORAGE_KEY, newVol.toString());
    const event: VolumeChangeEvent = new CustomEvent(VOLUME_CHANGE_EVENT, {
      detail: { volume: newVol },
    });
    window.dispatchEvent(event);
  };

  return (
    <div
      className={cn("relative flex items-center", className)}
      onMouseEnter={() => {
        setIsHovered(true);
      }}
      onMouseLeave={() => {
        setIsHovered(false);
      }}
    >
      <div className="text-navbar-text-primary navbar-expanded:text-navbar-text-secondary hover:scale-110 transition-transform p-1">
        {volume === 0 ? (
          <VolumeX width={18} height={18} />
        ) : volume > 0.5 ? (
          <Volume2 width={18} height={18} />
        ) : (
          <Volume1 width={18} height={18} />
        )}
      </div>

      <div
        className={cn(
          "absolute top-full left-1/2 -translate-x-1/2 mt-2 bg-white rounded-md shadow-lg border border-gray-200 p-2 z-10 transition-all duration-200",
          isHovered ? "block" : "hidden",
        )}
      >
        {/* Invisible bridge to prevent gap */}
        <div className="absolute -top-2 left-1/2 -translate-x-1/2 w-11 h-2" />
        <div className="flex flex-col items-center gap-1">
          <span className="font-body text-xs w-8 text-center text-gray-600">
            {Math.round(volume * 100)}%
          </span>

          <div className="relative h-24 w-6 flex items-center justify-center">
            <input
              type="range"
              min={0}
              max={1}
              step={0.05}
              value={volume}
              onChange={handleVolumeChange}
              aria-label="Volume level"
              aria-valuetext={`${Math.round(volume * 100)}%`}
              aria-orientation="vertical"
              className="absolute inset-0 w-24 h-6 cursor-pointer -rotate-90 origin-center left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 touch-none"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default VolumeControl;
